create type public.app_role as enum ('admin');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create function public.has_role(_user_id uuid, _role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create policy own_roles on public.user_roles for select to authenticated using(user_id=auth.uid());
create function public.assign_jami_admin() returns trigger language plpgsql security definer set search_path=public as $$ begin if lower(new.email)='accounting@jamicleaninginc.com' and new.email_confirmed_at is not null then insert into public.user_roles(user_id,role) values(new.id,'admin') on conflict do nothing; end if; return new; end $$;
create trigger jami_admin_on_confirmation after insert or update of email_confirmed_at on auth.users for each row execute function public.assign_jami_admin();
create table public.contact_submissions(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 100), contact text not null check(length(contact) between 3 and 255), service text not null default '', timing text not null default '', message text not null default '' check(length(message)<=3000), status text not null default 'new' check(status in ('new','reviewed','completed')), created_at timestamptz not null default now());
grant select,update on public.contact_submissions to authenticated; grant all on public.contact_submissions to service_role;
alter table public.contact_submissions enable row level security;
create policy admin_read_submissions on public.contact_submissions for select to authenticated using(public.has_role(auth.uid(),'admin'));
create policy admin_update_submissions on public.contact_submissions for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.maintenance_requests(id uuid primary key default gen_random_uuid(), user_id uuid not null, subject text not null check(length(subject) between 1 and 150), description text not null check(length(description) between 1 and 5000), priority text not null default 'normal' check(priority in ('normal','urgent')), status text not null default 'submitted' check(status in ('submitted','in_progress','completed')), recipient text not null default 'peacecountrymarketing@gmail.com' check(recipient='peacecountrymarketing@gmail.com'), email_status text not null default 'not_sent' check(email_status in ('not_sent','sent')), created_at timestamptz not null default now());
grant select,insert,update on public.maintenance_requests to authenticated; grant all on public.maintenance_requests to service_role;
alter table public.maintenance_requests enable row level security;
create policy admin_read_maintenance on public.maintenance_requests for select to authenticated using(public.has_role(auth.uid(),'admin'));
create policy admin_insert_maintenance on public.maintenance_requests for insert to authenticated with check(public.has_role(auth.uid(),'admin') and user_id=auth.uid() and email_status='not_sent');
create policy admin_update_maintenance on public.maintenance_requests for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.site_page_views(id uuid primary key default gen_random_uuid(), visitor_id uuid not null, path text not null check(path in ('/','/faq','/blog','/book')), created_at timestamptz not null default now());
grant select on public.site_page_views to authenticated; grant all on public.site_page_views to service_role;
alter table public.site_page_views enable row level security;
create policy admin_read_views on public.site_page_views for select to authenticated using(public.has_role(auth.uid(),'admin'));
create index site_views_created_idx on public.site_page_views(created_at);
create function public.record_page_view(_visitor_id uuid,_path text) returns void language plpgsql security definer set search_path=public as $$ begin if _path not in ('/','/faq','/blog','/book') then raise exception 'Invalid page'; end if; insert into public.site_page_views(visitor_id,path) values(_visitor_id,_path); end $$;
revoke all on function public.record_page_view(uuid,text) from public; grant execute on function public.record_page_view(uuid,text) to anon,authenticated;
create function public.admin_analytics(_days integer default 30) returns jsonb language plpgsql security invoker set search_path=public as $$ declare result jsonb; begin if not public.has_role(auth.uid(),'admin') then raise exception 'Admin access required'; end if; if _days not in (7,30,90) then raise exception 'Invalid date range'; end if; select jsonb_build_object('views',count(*),'visitors',count(distinct visitor_id),'pages',coalesce((select jsonb_agg(p) from (select path,count(*) as views from public.site_page_views where created_at>=now()-make_interval(days=>_days) group by path order by count(*) desc) p),'[]'::jsonb),'daily',coalesce((select jsonb_agg(d order by day) from (select created_at::date as day,count(*) as views from public.site_page_views where created_at>=now()-make_interval(days=>_days) group by created_at::date) d),'[]'::jsonb)) into result from public.site_page_views where created_at>=now()-make_interval(days=>_days); return result; end $$;
revoke all on function public.admin_analytics(integer) from public; grant execute on function public.admin_analytics(integer) to authenticated;